#include <cstdio>
#include <cmath>
#include <cstdlib>
#include <cstring>
int main(int argc,char**argv){
  int n=atoi(argv[1]);
  unsigned long long m; double pi=M_PI; memcpy(&m,&pi,8);
  printf("M_PI=%016llx\n",m);
  for(int i=0;i<n*2;i++){
    double t=double(i)/(n*2);
    double radius=t;
    double angle=4.0*M_PI*t;
    double x=radius*std::cos(angle), y=radius*std::sin(angle);
    unsigned long long a,b; memcpy(&a,&x,8); memcpy(&b,&y,8);
    printf("%d %016llx %016llx\n",i,a,b);
  }
  return 0;
}
EOF
cat > /tmp/dump/d.rs <<'EOF'
use std::f64::consts::PI;
fn main(){
  let a:Vec<String>=std::env::args().collect();
  let n:i32=a[1].parse().unwrap();
  println!("M_PI={:016x}", PI.to_bits());
  let count=n.wrapping_mul(2);
  let mut i:i32=0;
  while i<count {
    let t=f64::from(i)/f64::from(count);
    let radius=t;
    let angle=4.0*PI*t;
    let x=radius*angle.cos(); let y=radius*angle.sin();
    println!("{} {:016x} {:016x}", i, x.to_bits(), y.to_bits());
    i+=1;
  }
}
EOF
